INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23201, 'Mark 3:32', 'Mark', 3, 32, '&nbsp;ګڼ خلق ترې چاپېره ناست وُو او هغوئ ورته ووئيل چې، ”ستا مور او وروڼه بهر ولاړ دى، هغوئ تا سره مِلاوېدل غواړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23202, 'Mark 3:33', 'Mark', 3, 33, '&nbsp;هغۀ جواب ورکړو، ”زما مور او زما وروڼه څوک دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23203, 'Mark 3:34', 'Mark', 3, 34, '&nbsp;او هغه ګېرچاپېره ناستو خلقو ته يې وکتل او وې فرمائيل چې، ”زما مور او وروڼه دا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23204, 'Mark 3:35', 'Mark', 3, 35, '&nbsp;څوک چې د خُدائ پاک رضا کوى، هغه زما ورور خور او مور ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23205, 'Mark 4:1', 'Mark', 4, 1, '&nbsp;عيسىٰ يو ځل بيا د درياب په غاړه تعليم شروع کړو او دومره ډېر خلق ورته راټول شوى وُو چې هغه ترې په درياب کښې کشتۍ ته وختو او هلته کښېناستو، او نور ټول خلق د درياب په غاړه په اوچه ورته راټول شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23206, 'Mark 4:2', 'Mark', 4, 2, '&nbsp;او هغۀ هغوئ ته په مِثالونو کښې د ډېرو خبرو تعليم ورکړو. او په خپل تعليم کښې هغۀ هغوئ ته وفرمائيل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23207, 'Mark 4:3', 'Mark', 4, 3, '&nbsp;”واورئ، يو زميندار د کروندې دپاره بهر لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23208, 'Mark 4:4', 'Mark', 4, 4, '&nbsp;نو چې کله هغۀ په خپل پټى کښې تخم نوستلو نو څۀ تخم ترې نه په لاره پرېوتو نو مارغان راغلل هغه يې وخوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23209, 'Mark 4:5', 'Mark', 4, 5, '&nbsp;څۀ تخم په کاڼيزه زمکه پرېوتو چرته چې لږه شان خاوره وه او دا زر راوټوکېدلو ځکه چې هلته لاندې نوره خاوره نۀ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23210, 'Mark 4:6', 'Mark', 4, 6, '&nbsp;خو چې نمر راوختلو نو هغه کچه بوټى يې وسوزول او هغه اوچ شُو ځکه چې جرړې يې نۀ وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23211, 'Mark 4:7', 'Mark', 4, 7, '&nbsp;څۀ تخم په غنو کښې پرېوتو، ازغى لوئ شول او فصل يې لاندې کړو او مېوه دانه يې ونۀ نيوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23212, 'Mark 4:8', 'Mark', 4, 8, '&nbsp;او څۀ تخم په زرخيزه زمکه پرېوتو چرته چې هغه راوټوکېدو او لوئ شو او يو په دېرش يو په شپېتۀ او يو په سل غله يې وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23213, 'Mark 4:9', 'Mark', 4, 9, '&nbsp;هغۀ بيا وفرمائيل، ”کۀ څوک د اورېدو غوږونه لرى نو هغه دې واورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23214, 'Mark 4:10', 'Mark', 4, 10, '&nbsp;هر کله چې عيسىٰ د ګڼې نه فارغ شو نو دولسو مريدانو او نورو د هغۀ نه ځانله د مِثالونو په حقله تپوس وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23215, 'Mark 4:11', 'Mark', 4, 11, '&nbsp;هغۀ جواب ورکړو چې، ”تاسو ته د خُدائ پاک د بادشاهۍ راز درکړے شوے دے خو هغه څوک چې بهر دى، هغوئ ته هره خبره په مِثالونو کښې کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23216, 'Mark 4:12', 'Mark', 4, 12, '&nbsp;لکه څنګه چې صحيفې وائى، زۀ چې څۀ کوم هغوئ به يې په سترګو وينى، خو څۀ به هم ترې نۀ زده کوى، هغوئ به اورى خو پوهيږى به پرې نه، ګنې نو هغوئ به خُدائ پاک ته راوګرځى او وبه بخښلے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23217, 'Mark 4:13', 'Mark', 4, 13, '&nbsp;بيا عيسىٰ هغوئ ته وفرمائيل، ”ولې تاسو په دې مِثال پوهه نۀ شوئ؟ نو بيا به تاسو په نورو مِثالونو څنګه پوهه شئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23218, 'Mark 4:14', 'Mark', 4, 14, '&nbsp;زميندار کلام کَرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23219, 'Mark 4:15', 'Mark', 4, 15, '&nbsp;د لارې په غاړه هغه خلق دى چرته چې کلام کَرلے کيږى، او چې کلام واورى نو شېطان سمدستى راشى او کَرلے شوے کلام د دوئ نه يوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23220, 'Mark 4:16', 'Mark', 4, 16, '&nbsp;دغسې هم هغه دى چې په کاڼيزه زمکه کَرلے شوى دى، څنګه چې دوئ کلام واورى نو په خوشحالۍ سره يې سمدستى قبول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23221, 'Mark 4:17', 'Mark', 4, 17, '&nbsp;خو چې جرړې يې نۀ وى، نو د زغم طاقت په کښې د لږ وخت دپاره وى، نو بيا کله چې د کلام په وجه په هغوئ تکليف يا سختى راشى نو بيا سمدستى هغوئ تيندک وخورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23222, 'Mark 4:18', 'Mark', 4, 18, '&nbsp;نور خلق هغوئ دى چې په غنو کښې وکرلے شُو. دا هغه خلق دى چې کلام اورى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23223, 'Mark 4:19', 'Mark', 4, 19, '&nbsp;خو د دُنيا غم او د مال دولت لالچ او د نورو څيزونو خواهشات په مينځ کښې راشى او د کلام مرۍ خپه کړى او کلام بې‌مېوې پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23224, 'Mark 4:20', 'Mark', 4, 20, '&nbsp;او بيا هغه خلق دى چې تخم يې په زرخيزه زمکه پرېوتو، دوئ کلام واورى او قبول يې کړى او يو په دېرش، يو په شپېتۀ او يو په سل مېوه ونيسى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23225, 'Mark 4:21', 'Mark', 4, 21, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”ولې تاسو ډيوه د لوښى يا د کټ لاندې د کېښودو دپاره راوړئ؟ او ولې هغه تاسو په ډيوټ نۀ ږدئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23226, 'Mark 4:22', 'Mark', 4, 22, '&nbsp;خو داسې پټ څيز نشته چې ښکاره به نۀ شى او نۀ داسې پټ راز شته چې هغه به ښکاره نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23227, 'Mark 4:23', 'Mark', 4, 23, '&nbsp;کۀ څوک د اورېدو غوږونه لرى نو هغه دې واورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23228, 'Mark 4:24', 'Mark', 4, 24, '&nbsp;عيسىٰ دا هم وفرمائيل، ”ما ته توجو وکړئ چې څۀ اورئ، نو چې څنګه تاسو د بل ناپ تول کوئ، دغه رنګ به ستاسو ناپ تول کولے شى، بلکې لږ څۀ زيات.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23229, 'Mark 4:25', 'Mark', 4, 25, '&nbsp;ځکه د هر چا سره چې څۀ وى هغۀ له به نور هم ورکړے شى، خو د چا سره چې نۀ وى هغۀ نه به هغه څۀ هم واخستلے شى چې ورسره وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23230, 'Mark 4:26', 'Mark', 4, 26, '&nbsp;عيسىٰ وفرمائيل، ”د خُدائ پاک بادشاهى داسې ده چې کۀ يو سړے تخم په زمکه کښې کَرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23231, 'Mark 4:27', 'Mark', 4, 27, '&nbsp;او کۀ هغه د شپې او ورځې اودۀ او يا ويښ وى خو هغه په دې نۀ پوهيږى چې په زمکه کښې تخم په خپله څنګه راټوکيږى او لوئيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23232, 'Mark 4:28', 'Mark', 4, 28, '&nbsp;زمکه له ځان نه غله پخپله پېدا کوى، وړومبے تېغه، بيا وَږى او بيا په وَږى کښې تيارې دانې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23233, 'Mark 4:29', 'Mark', 4, 29, '&nbsp;خو هر کله چې فصل پوخ شى نو هغه ورپسې لور راواخلى ځکه چې د فصل د لو کولو وخت راغلے وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23234, 'Mark 4:30', 'Mark', 4, 30, '&nbsp;عيسىٰ دا هم وفرمائيل، ”مونږ د خُدائ پاک بادشاهى د څۀ شى سره بيانولے شُو، يا د هغې دپاره کوم مثال استعمالولے شُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23235, 'Mark 4:31', 'Mark', 4, 31, '&nbsp;دا د شړشمو د هغه تخم په شان ده کله چې په زمکه وکرلے شى، دا په زمکه کښې د ټولو تخمونو نه ورکوټے وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23236, 'Mark 4:32', 'Mark', 4, 32, '&nbsp;نو چې وکرلے شى دا د باغ د ټولې کروندې نه ډېر لوئيږى او دومره لوئ څانګې خورې کړى چې د هوا مارغان يې په سورى کښې جالې جوړوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23237, 'Mark 4:33', 'Mark', 4, 33, '&nbsp;هغۀ به کلام دغسې په ډېرو مِثالونو ورته اورولو څومره چې هغوئ برداشت کولے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23238, 'Mark 4:34', 'Mark', 4, 34, '&nbsp;هغۀ د هغوئ سره د مِثالونو نه بغېر کلام ونۀ کړو خو ځان له يې خپلو مريدانو ته هر څۀ واضحه کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23239, 'Mark 4:35', 'Mark', 4, 35, '&nbsp;په هغه ورځ ماښام هغۀ مريدانو ته وفرمائيل، ”راځئ چې د درياب پورې غاړې ته لاړ شُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23240, 'Mark 4:36', 'Mark', 4, 36, '&nbsp;هغوئ ګڼه پاتې کړه او مريدانو هغه د ځان سره په کشتۍ کښې بوتلو په کومه کښې چې هغه ناست وو او د هغۀ سره نورې کِشتۍ هم وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23241, 'Mark 4:37', 'Mark', 4, 37, '&nbsp;خو په درياب کښې يو زورَور طوفان راغلو، چپو کِشتۍ داسې ووهله چې ډوبېدو ته نزدې شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23242, 'Mark 4:38', 'Mark', 4, 38, '&nbsp;عيسىٰ وروستو په کِشتۍ کښې اودۀ وو او بالښت يې سر لاندې پروت وو. هغوئ هغه رابېدار کړو او ورته يې ووئيل، ”مالِکه، مونږ ډوبيږو، تا سره څۀ غم نشته؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23243, 'Mark 4:39', 'Mark', 4, 39, '&nbsp;هغه بېدار شو، باد يې ورټلو او درياب ته يې وفرمائيل چې، ”په آرام شه، ودرېږه.“ باد ودرېدلو نو په هغه ساعت قلاره قلارې شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23244, 'Mark 4:40', 'Mark', 4, 40, '&nbsp;هغۀ هغوئ ته وفرمائيل چې، ”تاسو ولې دومره يرېږئ، تاسو لا اوس هم ايمان نۀ لرئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23245, 'Mark 4:41', 'Mark', 4, 41, '&nbsp;هغوئ يرې اخستى وُو او يو بل ته يې ووئيل، چې، ”دا لا څۀ قِسم سړے دے چې هوا او چپې يې هم حکم منى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23246, 'Mark 5:1', 'Mark', 5, 1, '&nbsp;او هغوئ د درياب بلې غاړې ته د ګِراسينيانو علاقې ته راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23247, 'Mark 5:2', 'Mark', 5, 2, '&nbsp;او چې کله عيسىٰ د کشتۍ نه راکوز شو، نو سمدستى يو سړے چې پيريانو نيولے وو د قبرستان نه د هغۀ سره د مِلاوېدو دپاره راووتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23248, 'Mark 5:3', 'Mark', 5, 3, '&nbsp;هغه په قبرستان کښې اوسېدو او هيچا هم قابو کولے نۀ شو، تر دې چې په زنځيرونو کښې هم تړلے کېدے نۀ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23249, 'Mark 5:4', 'Mark', 5, 4, '&nbsp;ځکه چې هغۀ ته يې څو څو ځله زنځيرونه او هتکړۍ اچولې وې خو هغۀ زنځيرونه شلولى وُو او هتکړۍ يې ماتې کړې وې او دومره طاقتور هيڅوک نۀ وُو چې هغه يې قابو کړے وے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23250, 'Mark 5:5', 'Mark', 5, 5, '&nbsp;شپه او ورځ به هغۀ په قبرونو او د غرونو په خوا کښې چغې وهلې او ځان به يې په کاڼو زخمى کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23251, 'Mark 5:6', 'Mark', 5, 6, '&nbsp;کله چې هغۀ عيسىٰ د لرې نه وليدلو نو هغۀ ورمنډه کړه او سجده يې ورته وکړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23252, 'Mark 5:7', 'Mark', 5, 7, '&nbsp;او په چغو يې ووئيل، ”اے عيسىٰ، د خُدائ تعالىٰ زويه، تۀ زما نه څۀ غواړې؟ خُدائ ته وګوره چې ما مۀ په عذابوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23253, 'Mark 5:8', 'Mark', 5, 8, '&nbsp;ځکه چې عيسىٰ هغۀ ته دا وفرمائيل، ”اے پيريانو، د دې سړى نه راوځئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23254, 'Mark 5:9', 'Mark', 5, 9, '&nbsp;بيا عيسىٰ د هغۀ نه تپوس وکړو چې، ”نوم دې څۀ دے؟“ هغۀ جواب ورکړو چې، ”زما نوم لښکر دے، ځکه چې مونږ ډېر يُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23255, 'Mark 5:10', 'Mark', 5, 10, '&nbsp;او هغۀ مِنت زارى ورته وکړه چې دوئ د دې علاقې نه ونۀ شړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23256, 'Mark 5:11', 'Mark', 5, 11, '&nbsp;نو هلته د غرۀ په خوا کښې د خنزيرانو يوه لويه رمه څرېدله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
